rss.channel:
{{ site.title | xml_escape }}
{{ site.url }}{{ site.baseurl }}/
{{ site.description | xml_escape }}
en
{{ site.time | date_to_rfc822 }}

{% assign entries = site.data.news | sort: "date" | reverse %}
{% for entry in entries limit: 20 %}
{%- if entry.url contains "://" -%}
  {%- assign link = entry.url -%}
{%- elsif entry.url -%}
  {%- assign link = entry.url | absolute_url -%}
{%- else -%}
  {%- assign link = '/news' | absolute_url -%}
{%- endif -%}
{%- assign plain = entry.en | markdownify | strip_html | strip -%}


  {{ plain | xml_escape }}
  {{ plain | xml_escape }}
  {{ entry.date | date_to_rfc822 }}
  {{ link }}
  news-{{ entry.date | date: "%Y-%m-%d" }}-{{ entry.en | slugify }}

{% endfor %}
